        try checkTypedTailWeightBytes(col_embed, try checkedTensorElements(width, dim - dim / 2), col_dtype);
        if (has_temporal) try checkTypedTailWeightBytes(temporal_embed, dim, temporal_dtype);
        if (dst_count == 0) return;
