        self: *KernelModule,
        ctx: *context_mod.CudaContext,
        dst: buffer_mod.DeviceBuffer,
        q: buffer_mod.DeviceBuffer,
        k: buffer_mod.DeviceBuffer,
        v: buffer_mod.DeviceBuffer,
        q_r: buffer_mod.DeviceBuffer,
        k_r: buffer_mod.DeviceBuffer,
