        var d_scores_ptr = d_scores.ptr;
        var q_ptr = q.ptr;
        var k_ptr = k.ptr;
        var v_ptr = v.ptr;
        var q_r_ptr = q_r.ptr;
        var k_r_ptr = k_r.ptr;
        var mask_ptr = mask.ptr;
