        var head_dim_u32 = try toU32(head_dim);
        var params = [_]?*anyopaque{
            @ptrCast(&probabilities_ptr),
            @ptrCast(&d_scores_ptr),
            @ptrCast(&q_ptr),
            @ptrCast(&k_ptr),
            @ptrCast(&v_ptr),
