            @ptrCast(&k_ptr),
            @ptrCast(&v_ptr),
            @ptrCast(&q_r_ptr),
            @ptrCast(&k_r_ptr),
            @ptrCast(&mask_ptr),
            @ptrCast(&batch_u32),
            @ptrCast(&seq_len_u32),
