        var first_ptr = first.ptr;
        var second_ptr = second.ptr;
        var third_ptr = third.ptr;
        var input_ptr = input.ptr;
        var rows_u32 = try toU32(rows);
        var dim_u32 = try toU32(dim);
        var params = [_]?*anyopaque{
