    try ctx.launchGraph(exec);
    try ctx.synchronize();

    const out = try allocator.alloc(f32, count);
    defer allocator.free(out);
    try buf.copyToHost(&ctx, std.mem.sliceAsBytes(out));
    try ctx.synchronize();
    for (out) |v| {
        if (@abs(v - 4.25) > 0.00001) return error.CudaSmokeMismatch;
    }
}

