    defer input.free(&ctx);
    var weight = try buffer_mod.DeviceBuffer.alloc(&ctx, weight_raw.len);
    defer weight.free(&ctx);
    var bias = try buffer_mod.DeviceBuffer.alloc(&ctx, bias_data.len * @sizeOf(f32));
