    try output_b.copyToHost(&ctx, std.mem.sliceAsBytes(out));
    try ctx.synchronize();
    try expectApproxSlice(out, &expected_bias, 0.1);
    try output_c.copyToHost(&ctx, std.mem.sliceAsBytes(out));
